head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil25502";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil25502.onpageload' });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {

    document.body.scroll = "yes";
    scwin.PopupAutoResize();
};

// [A] 초기 목록 미해결 — jldfil25502: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_changeDiv_onclick
 * @description btn_changeDiv 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_changeDiv_onclick = function(e){
    try {
        scwin.changeDiv(1)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25502.btn_changeDiv_onclick' }); }
};

/**
 * @method
 * @name btn_changeDiv_onmouseover
 * @description btn_changeDiv onmouseover 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_changeDiv_onmouseover = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.style.textDecoration='underline';

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25502.btn_changeDiv_onmouseover' }); }
};

/**
 * @method
 * @name btn_changeDiv_onmouseout
 * @description btn_changeDiv onmouseout 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_changeDiv_onmouseout = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.style.textDecoration='none';

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25502.btn_changeDiv_onmouseout' }); }
};

