/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function(e){
    try {
        scwin.close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25502.btn_Close_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_eduCompltList_2_fmt_column1
 * @description grd edu Complt List 2 fmt column1 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_eduCompltList_2_fmt_column1 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_eduCompltList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "eduKindCd") ?? '') : '');
        if (v === '11') { return "공시책임자"; }
        if (v === '12') { return "공시담당자(정)"; }
        if (v === '13') { return "공시담당자(부)"; }
        if (v === '14') { return "공시대리인"; }
        if (v === '15') { return "공시담당보조자"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_eduCompltList_2.column1" }); return String(data ?? ''); }
};

/**
 * @method
 * @name PopupAutoResize
 * @description Popup Auto Resize 처리
 * @returns {void}
 * @hidden N
 */
scwin.PopupAutoResize = function () {

    let thisX = parseInt(document.body.scrollWidth);
    let thisY = parseInt(document.body.scrollHeight);
    const maxThisX = screen.width - 50;
    const maxThisY = screen.height - 50;
    let marginY = 0;
    if (navigator.userAgent.indexOf("MSIE") > 0) {
        marginY = 70;
    } else {
        if (navigator.userAgent.indexOf("Firefox") > 0) {
            marginY = 50;
        } else {
            if (navigator.userAgent.indexOf("Opera") > 0) {
                marginY = 30;
            } else {
                if (navigator.userAgent.indexOf("Netscape") > 0) {
                    marginY = -2;
                }
            }
        }
    }
    if (thisX > maxThisX) {
        document.body.scroll = "yes";
        thisX = maxThisX;
    }
    if (thisY > maxThisY - marginY) {
        document.body.scroll = "yes";
        thisX += 19;
        thisY = maxThisY - marginY;
    }
    document.body.scroll = "yes";

};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    $c.win.closePopup();
};

/**
 * @method
 * @name changeYear
 * @description change Year 처리
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.changeYear = function (val) {
    let paramYear = null;
    if (val === "pre") {
        paramYear = paramYear - 1;
    } else {
        if (val === "next") {
            paramYear = paramYear + 1;
        }
    }
    const url = "/outer/disclsSchdl.do?method=eduSchdlView&thisYear=" + paramYear;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.setPageFrameSrc($c.win.getFrame(), (function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url));
};

/**
 * @method
 * @name changeDiv
 * @description change Div 처리
 * @param {String} tabId 탭 id
 * @returns {void}
 * @hidden N
 */
scwin.changeDiv = function (tabId) {
    if (tabId === 1) {
        $("#td_tab2").removeClass("td_tab_2").addClass("td_tab_1");
        $("#td_tab1").addClass("td_tab_2");
        ($c.util.getComponent("div_schdl") && $c.util.getComponent("div_schdl").show ? $c.util.getComponent("div_schdl").show() : console.warn('[sdd] show 대상 미해결: ' + "div_schdl"));
        ($c.util.getComponent("div_info") && $c.util.getComponent("div_info").hide ? $c.util.getComponent("div_info").hide() : console.warn('[sdd] hide 대상 미해결: ' + "div_info"));
        scwin.PopupAutoResize();
    } else {
        if (tabId === 2) {
            $("#td_tab1").removeClass("td_tab_2").addClass("td_tab_1");
            $("#td_tab2").addClass("td_tab_2");
            ($c.util.getComponent("div_schdl") && $c.util.getComponent("div_schdl").hide ? $c.util.getComponent("div_schdl").hide() : console.warn('[sdd] hide 대상 미해결: ' + "div_schdl"));
            ($c.util.getComponent("div_info") && $c.util.getComponent("div_info").show ? $c.util.getComponent("div_info").show() : console.warn('[sdd] show 대상 미해결: ' + "div_info"));
            scwin.PopupAutoResize();
        }
    }
};
